def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def ranges(size, separators):
        bounds = [-1] + separators + [size]
        return [(bounds[i] + 1, bounds[i + 1])
                for i in range(len(bounds) - 1)
                if bounds[i] + 1 < bounds[i + 1]]

    row_ranges = ranges(h, sep_rows)
    col_ranges = ranges(w, sep_cols)

    cells = [
        grid[r][c]
        for r in range(h) for c in range(w)
        if r not in sep_rows and c not in sep_cols
    ]
    background = max(set(cells), key=cells.count)

    result = []
    for r0, r1 in row_ranges:
        row = []
        for c0, c1 in col_ranges:
            count = sum(grid[r][c] != background
                        for r in range(r0, r1)
                        for c in range(c0, c1))
            row.append(1 if count >= 2 else background)
        result.append(row)
    return result
